import { index, integer, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";

const timestamptz = (name: string) => timestamp(name, { withTimezone: true, mode: "date" });

/**
 * A conversation. `id` is a UUIDv7 generated by the app. `next_seq` is the per-session message
 * counter (advanced under the row lock by the messages module) and is never exposed.
 * `last_activity_at` moves only when a turn is admitted, never on a settings change.
 */
export const sessions = pgTable(
  "sessions",
  {
    id: uuid("id").primaryKey(),
    title: text("title"),
    provider: text("provider").notNull(),
    model: text("model").notNull(),
    systemPrompt: text("system_prompt"),
    nextSeq: integer("next_seq").notNull().default(1),
    lastActivityAt: timestamptz("last_activity_at").notNull(),
    createdAt: timestamptz("created_at").notNull().defaultNow(),
    updatedAt: timestamptz("updated_at").notNull().defaultNow(),
  },
  // NULLS FIRST is what a plain `ORDER BY … DESC` means; drizzle-kit would otherwise emit
  // NULLS LAST and the list query could not use the index for its ordering.
  (table) => [
    index("sessions_last_activity_at_id_idx").on(
      table.lastActivityAt.desc().nullsFirst(),
      table.id.desc().nullsFirst(),
    ),
  ],
);
